<?php require '../config/database.php';auth();$rows=$pdo->query("SELECT p.*,c.name customer FROM payments p LEFT JOIN customers c ON c.id=p.customer_id ORDER BY p.id DESC")->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>المدفوعات</h1><a class="btn" href="add.php">تسجيل دفعة</a><table><tr><th>#</th><th>العميل</th><th>المبلغ</th><th>الطريقة</th><th>الملاحظة</th><th>التاريخ</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=htmlspecialchars($r['customer']??'غير محدد')?></td><td><?=$r['amount']?></td><td><?=$r['payment_method']?></td><td><?=htmlspecialchars($r['notes'])?></td><td><?=$r['created_at']?></td></tr><?php endforeach;?></table></main>
